<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {syncAdminVersion} from './adminVersion.js'
import {adminFetch} from './adminApi.js'
import {compareVersions} from '../../../shared/releases.js'
const data=ref(null),error=ref(''),notice=ref(''),busy=ref(false),restoreId=ref(''),confirmation=ref(''),enabled=ref(false),hour=ref(3),retention=ref(7)
let timer,disposed=false,settingsLoaded=false
const updateAvailable=computed(()=>data.value?.release&&compareVersions(data.value.release.version,(data.value.installed_version||data.value.current_version))>0)
const labels={queued:'В очереди',check:'Проверка GitHub',download:'Загрузка и проверка релиза',dependencies:'Подготовка зависимостей',maintenance:'Включение обслуживания',backup:'Создание полной копии',verify:'Проверка восстановления во временной базе',apply:'Установка релиза',health:'Проверка работоспособности',restore:'Восстановление',done:'Готово'}
const kinds={check:'Проверка релизов',backup:'Резервная копия',verify:'Проверка копии',update:'Обновление CMS',restore:'Восстановление'}
const time=value=>value?new Date(value).toLocaleString('ru-RU'):'Ещё не выполнялась'
const bytes=value=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(value/1048576)+' МБ'
async function load(){
 try{const r=await adminFetch('/api/admin/system');if(!r.ok)throw Error('Сервер временно недоступен. Во время копирования или обновления это ожидаемо; проверка продолжится автоматически.');const value=await r.json();if(disposed)return;data.value=value;syncAdminVersion(value);error.value='';if(!settingsLoaded&&value.schedule){enabled.value=value.schedule.enabled;hour.value=value.schedule.hour_utc;retention.value=value.schedule.retention_days;settingsLoaded=true}}
 catch(e){if(!disposed)error.value=e.message}
}
async function command(body){busy.value=true;notice.value='';error.value='';try{const r=await adminFetch('/api/admin/system/jobs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const value=await r.json();if(!r.ok)throw Error(value.error||'Операция отклонена');notice.value=body.kind==='schedule'?'Расписание сохранено':'Операция принята. Страницу можно оставить открытой.';restoreId.value='';confirmation.value='';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function update(){if(confirm('Создать полную проверенную резервную копию и установить NOVA '+data.value.release.version+'? На время переключения сайт будет недоступен.'))command({kind:'update',version:data.value.release.version})}
function restore(){if(confirmation.value==='ВОССТАНОВИТЬ'&&confirm('Восстановить выбранное состояние базы, файлов и настроек? Изменения после даты копии будут заменены. Перед операцией будет создана копия текущего состояния.'))command({kind:'restore',backup_id:restoreId.value,confirm:confirmation.value})}
onMounted(async()=>{await load();if(!disposed)timer=setInterval(load,5000)})
onUnmounted(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
<section class="system-workspace">
 <div class="system-heading"><div><p class="eyebrow">СИСТЕМА</p><h2>Обновления и резервные копии</h2><p>Установленная версия: <strong>{{data?.installed_version||data?.current_version||'…'}}</strong></p></div><button class="row-btn" :disabled="busy||!!data?.active" @click="command({kind:'check'})">Проверить релизы</button></div>
 <p v-if="data?.installed_version && data.installed_version!==data.current_version" class="alert" role="status">Файлы CMS: {{data.installed_version}}. Запущенный API: {{data.current_version}}. Дождитесь завершения операции; если расхождение сохранится, требуется проверка запуска API.</p>
 <p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <div v-if="data?.active" class="system-card" role="status"><h3>{{kinds[data.active.kind]}}</h3><p>{{labels[data.active.phase]||data.active.phase}}…</p><p>Во время согласованного копирования и установки сайт переходит в режим обслуживания. После запуска API страница обновит статус автоматически.</p></div>
 <div class="system-card" v-if="data"><h3>{{updateAvailable?'Доступно обновление '+data.release.version:'Версия CMS'}}</h3><p v-if="data.release&&!updateAvailable">Последний опубликованный релиз: {{data.release.version}}.</p><p v-if="!data.release">Опубликованные стабильные релизы пока не найдены.</p><p>Последняя успешная проверка: {{time(data.checked_at)}}</p><p v-if="data.error" class="alert">{{data.error}}</p><template v-if="data.release"><a :href="data.release.url" target="_blank" rel="noopener noreferrer">Открыть релиз GitHub</a><details><summary>Что изменилось</summary><pre class="release-notes">{{data.release.notes||'Описание не добавлено.'}}</pre></details></template><p v-if="!data.available">{{data.reason}}</p><button v-if="updateAvailable&&data.available" class="primary-btn" :disabled="busy||!!data.active" @click="update">Создать копию и обновить</button><p>Обновление устанавливает согласованные версии API, витрины и админки. Требования пакета и версия API тем проверяются до переключения.</p></div>
 <template v-if="data?.available">
 <div class="system-card"><h3>Полная резервная копия</h3><p>PostgreSQL, загруженные изображения, код с зависимостями, публичные файлы и серверные настройки. Копия проверяется реальным восстановлением в отдельную временную базу.</p><button class="primary-btn" :disabled="busy||!!data.active" @click="command({kind:'backup'})">Создать и проверить копию</button><p>Копии хранятся на этом сервере и не защищают от его полной потери. Администратору сервера нужно настроить защищённое хранение копий вне VDS; секреты через браузер не выдаются.</p></div>
 <form class="system-card" @submit.prevent="command({kind:'schedule',enabled,hour_utc:hour,retention_days:retention})"><h3>Ежедневные копии</h3><label class="system-checkbox"><input type="checkbox" v-model="enabled"> Включить ежедневную полную копию</label><div class="system-fields"><label>Час по UTC<select v-model.number="hour"><option v-for="n in 24" :key="n" :value="n-1">{{String(n-1).padStart(2,'0')}}:00 UTC</option></select></label><label>Срок хранения<select v-model.number="retention"><option :value="7">7 дней</option><option :value="14">14 дней</option><option :value="30">30 дней</option></select></label></div><p>Старые копии удаляются после создания новой. Две последние завершённые копии сохраняются. На время копии API приостанавливается.</p><button class="row-btn" :disabled="busy||!!data.active">Сохранить расписание</button></form>
 <div class="system-card"><h3>Сохранённые копии</h3><p v-if="!data.backups?.length">Копий этой системы пока нет. Ранее созданные вручную архивы не импортируются автоматически.</p><div v-for="backup in data.backups" :key="backup.id" class="backup-row"><div><strong>{{time(backup.created_at)}}</strong><p>NOVA {{backup.version}} · {{bytes(backup.size_bytes)}} · {{backup.verified?'Восстановление проверено':'Не проверена'}}</p><small>{{backup.id}}</small></div><div class="system-buttons"><button class="row-btn" :disabled="busy||!!data.active" @click="command({kind:'verify',backup_id:backup.id})">Проверить</button><button class="row-btn" :disabled="busy||!!data.active||!backup.verified" @click="restoreId=backup.id;confirmation=''">Восстановить…</button></div></div></div>
 <form v-if="restoreId" class="system-card" @submit.prevent="restore"><h3>Восстановление {{restoreId}}</h3><p>База, заказы, контент, файлы и настройки вернутся к дате копии. Текущее состояние предварительно сохраняется в отдельной проверенной копии.</p><label>Введите ВОССТАНОВИТЬ<input v-model="confirmation" autocomplete="off"></label><div class="system-buttons"><button type="button" class="row-btn" @click="restoreId=''">Отмена</button><button class="primary-btn" :disabled="busy||!!data.active||confirmation!=='ВОССТАНОВИТЬ'">Восстановить выбранную копию</button></div></form>
 <div class="system-card"><h3>Журнал операций</h3><p v-if="!data.jobs?.length">Операций пока нет.</p><div v-for="job in data.jobs" :key="job.id" class="system-job"><strong>{{kinds[job.kind]}} — {{job.status==='succeeded'?'Готово':'Ошибка'}}</strong><p>{{time(job.finished_at||job.started_at)}}</p><p v-if="job.error" class="alert">{{job.error}}</p><small v-if="job.recovery_snapshot">Копия перед операцией: {{job.recovery_snapshot}}</small></div></div>
 </template>
</section>
</template>
<style scoped>
.system-workspace{max-width:1100px;display:grid;gap:20px}.system-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.system-heading h2{margin:4px 0 12px}.system-card{border:1px solid #e0e5ed;border-radius:16px;background:white;padding:24px;display:grid;gap:12px}.system-card h3,.system-card p{margin:0}.system-card p{line-height:1.6;color:#566177}.system-card label{display:grid;gap:8px}.system-card input:not([type=checkbox]),.system-card select{padding:10px;border:1px solid #ccd3df;border-radius:8px;max-width:420px}.system-checkbox{display:flex!important;align-items:center}.system-fields{display:flex;flex-wrap:wrap;gap:20px}.system-buttons{display:flex;flex-wrap:wrap;gap:10px}.backup-row{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid #edf0f5}.backup-row small,.system-job small{overflow-wrap:anywhere;color:#68738a}.release-notes{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6;max-height:400px;overflow:auto}.system-job{border-bottom:1px solid #edf0f5;padding:12px 0}.system-job p{margin-top:8px}@media(max-width:700px){.system-heading,.backup-row{align-items:flex-start;flex-direction:column}.system-card{padding:18px}}
</style>
